INSERT OR REPLACE INTO "Growth Bonus Rate IN" SELECT coalesce(k0."Customer Group", error('cells name a member Customer Group does not have: ' || c."Customer Group")), coalesce(k1."Versions", error('cells name a member Versions does not have: ' || c."Versions")), coalesce(k2."Years", error('cells name a member Years does not have: ' || c."Years")), sum(c.value::DOUBLE)
FROM read_csv('cells/Growth Bonus Rate IN.csv', header = true, all_varchar = true) c LEFT JOIN "dim Customer Group" k0 ON k0.name = c."Customer Group" LEFT JOIN "dim Versions" k1 ON k1.name = c."Versions" LEFT JOIN "dim Years" k2 ON k2.name = c."Years"
GROUP BY ALL;
